R=pathlib.Path.cwd();H=R/'validation/targeted-lung-v08424/brigatinib'; p=json.load(open(H/'proposed/00562-brigatinib-therapy.json'));src=p['metadata']['source_url']; smpc='https://www.ema.europa.eu/en/documents/product-information/alunbrig-epar-product-information_en.pdf'; oral='https://healthservice.hse.ie/documents/7152/Classification_Document_for_Systemic_Anti-_Cancer_Therapy_SACT_Induced_Nausea__pWgDCrm.pdf'; ncis='https://healthservice.hse.ie/documents/7180/Supportive_Care_Antiemetics_for_inclusion_NCIS_Medical_Oncology.pdf'; alta1='https://pubmed.ncbi.nlm.nih.gov/34537440/'; alta='https://pubmed.ncbi.nlm.nih.gov/36065449/';date='2026-10-29'
sources=[{'id':'nccp','title':'NCCP 00562 Brigatinib Therapy v4, 18 August 2026','url':src},{'id':'smpc','title':'EMA Alunbrig product information and patient leaflet, current retrieved snapshot','url':smpc},{'id':'oral-antiemetic','title':'NCCP SACT Antiemetic Guidance V6 (2025), oral Tables 5 and 8','url':oral},{'id':'antiemetic','title':'NCCP NCIS Medical Oncology antiemetics V8 (2025), parenteral scope','url':ncis},{'id':'alta1l','title':'ALTA-1L final analysis: brigatinib versus crizotinib, 2021','url':alta1},{'id':'alta','title':'ALTA final analysis: crizotinib-refractory ALK-positive NSCLC, 2022','url':alta},{'id':'hse','title':'HSE cancer treatment side effects and urgent advice','url':'https://www2.hse.ie/conditions/chemotherapy/side-effects/'}]
scope='Brigatinib on its own for adults with ALK-positive advanced non-small-cell lung cancer: either after crizotinib (00562a) or before any ALK inhibitor (00562b). This is not an adjuvant course or a general pathway after every ALK inhibitor.'
schedule='The usual starting plan is 90 mg once daily for seven days, then 180 mg once daily if your team confirms the increase. Some people need a different dose. Treatment continues while helping and tolerable, with regular reviews and no fixed number of cycles.'
admin='Swallow the tablets whole with water, with or without food. Do not crush, chew or split them. Avoid grapefruit and grapefruit juice. If a dose is missed or you vomit after it, do not take an extra dose; take the next dose at its usual time. Contact the team for ongoing vomiting or difficulty keeping fluids or medicine down.'
monitor='Before starting: ALK result, blood count, kidney/liver tests, breathing-function assessment, ECG, blood pressure, fasting glucose, muscle enzyme CPK and pancreatic enzymes. Review breathing symptoms on days 8 and 15, then monthly or sooner if needed. ECG and blood pressure are checked every two weeks initially, then monthly. Liver tests are every two weeks for the first three months, then as advised. Blood count, kidneys, fasting glucose, CPK and pancreatic enzymes are usually checked monthly. Scans follow your Consultant’s plan.'
urgent='Contact your oncology team immediately for new or worsening breathlessness, cough or fever, especially during the first week but also later. Do not wait for a booked check. Urgent advice is also needed for fainting, a very slow heartbeat, chest pain, severe headache or vision changes, marked muscle pain/weakness, severe abdominal pain, persistent vomiting, unusual thirst or frequent urination, jaundice or severe diarrhoea. Major breathing difficulty, collapse or severe chest pain needs emergency help.'
restart='Do not restart or increase brigatinib yourself. A break of 14 days or more for a reason other than a side effect normally needs a new seven-day lead-in before the previously tolerated dose. A break because of a side effect follows a different recovery plan. Early lung inflammation can prevent the usual increase to 180 mg.'
repro='Discuss fertility before treatment. Effective non-hormonal contraception is advised for women during treatment and for at least four months after the last dose; men with partners who could become pregnant need effective contraception during treatment and for at least three months afterwards. Tell the team promptly about possible pregnancy. Breastfeeding must stop during treatment.'
risks=['Lung inflammation or early breathing reactions, which can be serious or fatal','Raised blood pressure or a slow heartbeat','Liver injury and abnormal liver tests','High blood glucose','Raised muscle enzyme with muscle pain or weakness','Raised pancreatic enzymes; report severe abdominal pain','Visual disturbance','Diarrhoea, nausea, vomiting, reduced appetite and fatigue','Skin rash and sensitivity to sunlight','Low blood counts and infection risk','Allergic reactions; pregnancy and fertility risks']
agent={'id':'brigatinib','name':'Brigatinib','alias':'Alunbrig','type':'Oral ALK-targeted therapy','mechanism':'Blocks an abnormal ALK growth signal','explanation':'An altered ALK gene can drive cancer-cell growth. Brigatinib blocks the activity of this signal. Testing confirms whether this target is present; the medicine can also affect healthy tissues, so regular checks and early symptom reporting matter.','visual':['ALK alteration drives growth','Brigatinib blocks ALK signalling','Cancer growth may slow'],'watch':'Report breathing changes immediately, especially in the first week. Follow the exact tablet strength and lead-in plan; check all new medicines with your pharmacist.','source_ids':['nccp','smpc'],'risks':risks,'symptoms':['Breathlessness / cough / fever','Dizziness / fainting / slow heartbeat','Headache / blood-pressure symptoms','Muscle pain or weakness','Vision changes','Thirst / frequent urination','Abdominal pain / nausea / vomiting','Diarrhoea','Skin rash / sun sensitivity','Fatigue / appetite change']}
stages=['Before starting','First seven days','Days 8–15 and first three months','Continuing treatment','Pause / stop / change']
lanes=[{'label':'Tablets and lead-in','kind':'treatment','cells':['Confirm indication and written dose','Usual 90 mg daily lead-in','Increase only if authorised; usual ongoing dose 180 mg daily','Daily treatment while beneficial and tolerated','Reason-specific restart; do not self-escalate'],'source_ids':['nccp'],'note':restart},{'label':'Breathing','kind':'monitoring','cells':['Pulmonary function and previous lung disease review','Report new cough or breathlessness immediately','Planned clinical checks on days 8 and 15','Monthly clinical assessment or sooner if symptoms','Follow recovery; early pneumonitis can prohibit escalation'],'source_ids':['nccp','smpc'],'note':'Scheduled reviews do not replace urgent reporting.'},{'label':'Liver tests','kind':'monitoring','cells':['Baseline liver profile','Early extra tests if clinically needed','Every two weeks for first three months','As clinically indicated afterwards','Review abnormal tests before any restart'],'source_ids':['nccp'],'note':'Baseline liver impairment and treatment-related liver injury have separate pathways.'},{'label':'Heart and blood pressure','kind':'monitoring','cells':['Baseline ECG and blood pressure','Symptoms require earlier assessment','Every two weeks during initial treatment period','Monthly or as clinically indicated','Review heart-rate/BP medicines after treatment changes'],'source_ids':['nccp'],'note':'The source calls this the first cycle but brigatinib is continuous oral treatment; no fixed chemotherapy cycle is inferred.'},{'label':'Blood, kidneys and metabolic tests','kind':'monitoring','cells':['FBC, renal profile, fasting glucose, CPK, amylase/lipase','Extra tests if symptoms occur','Monthly planned tests','Continue monthly or sooner if indicated','Resolve abnormalities and review dose limitations'],'source_ids':['nccp'],'note':'Glucose and enzyme tests are medicine-specific; they are not thyroid or immune-treatment monitoring.'},{'label':'Benefit, medicines and priorities','kind':'monitoring','cells':['ALK test, previous treatment, interactions and consent','Confirm tablet supply and contacts','Check adherence, interactions, symptoms and daily function','Disease assessment and scans per Consultant plan','Agree next treatment, follow-up and ongoing precautions'],'source_ids':['nccp','smpc'],'note':'There is no source-mandated fixed scan interval or adjuvant stop date.'}]
def item(title,text,ids=['nccp']):return {'title':title,'text':text,'source_ids':ids}
support=[item('One written tablet plan','Keep the current dose, tablet strengths and next review clear. Ask the pharmacist about safe storage, handling and returning unused tablets. Do not share medicines.',['smpc']),item('Anti-sickness medicines only if needed','Brigatinib has minimal-to-low oral sickness risk. The oral NCCP guidance uses anti-sickness medicines as required; your team chooses a suitable medicine, dose and duration. Persistent vomiting still needs advice.',['nccp','oral-antiemetic']),item('Food and other medicines','Take with or without food; avoid grapefruit. Check every prescription, herbal or non-prescription product, including St John’s wort, before starting or stopping it.',['smpc']),item('Skin and sunshine','Avoid prolonged sun exposure during treatment and for at least five days afterwards. Use protective clothing, a hat, broad-spectrum SPF 30 or higher sunscreen and lip balm. Report severe rash or sun reaction.',['smpc']),item('Symptoms and practical support','Keep the 24-hour oncology contact available. Ask early for help with symptoms, eating, tablet supply, work, travel or emotional wellbeing.',['hse'])]
chapters=[{'id':'treatment-purpose','title':'Why brigatinib is being considered','intro':'Confirm the cancer test and previous treatment before choosing this medicine.','items':[item('Two distinct treatment settings',scope),item('What the medicine does',agent['explanation'],['smpc']),item('How long treatment lasts',schedule)]},{'id':'tablets-at-home','title':'Taking treatment at home','intro':'Your prescription is the individual plan.','items':[item('Taking the tablets',admin,['nccp','smpc']),item('Lead-in and dose increase',schedule),item('After a pause',restart),item('Missed or vomited dose','Do not replace the dose or double the next dose. Resume at the next scheduled time and contact the team if symptoms prevent treatment.',['nccp'])]},{'id':'planned-checks','title':'Checks before and during treatment','intro':'Some important reactions appear before the next appointment.','items':[item('Baseline and ongoing checks',monitor),item('Breathing needs particular attention','Most early pulmonary reactions happen in the first seven days, but lung inflammation can occur later. Report new cough, breathlessness or fever straight away; the team may pause treatment while checking the cause.',['nccp','smpc']),item('Muscles, pancreas and glucose','Blood tests can identify changes before symptoms. Report muscle pain or weakness, severe abdominal pain, unusual thirst or frequent urination.',['nccp','smpc'])]},{'id':'everyday-safety','title':'Other medicines, skin and family planning','intro':'Ask before changing other medicines or the brigatinib dose.','items':[item('Interaction review','Some antibiotics, antifungals, antivirals, seizure medicines and herbal products can alter treatment. Your oncology pharmacist must review the complete medicine list. Do not change existing medicines yourself.',['smpc']),item('Sun protection',support[3]['text'],['smpc']),item('Pregnancy, breastfeeding and fertility',repro,['smpc']),item('Driving and daily tasks','Blurred vision, dizziness or fatigue can affect driving and machinery. Avoid these activities when affected and discuss persistent symptoms.',['smpc'])]},{'id':'warning-signs','title':'When to seek help','intro':'Follow your treating hospital’s urgent-contact instructions.','items':[item('Call promptly',urgent,['nccp','smpc']),item('When you call','Give the medicine, current dose, when symptoms started and when the last dose was taken. Say whether you can drink, pass urine and manage daily activities; do not delay calling to collect details.',['hse'])]}]
patient={'schema_version':1,'content_version':'0.84.24','suite_release':'0.84.24','service_kind':'targeted','review_status':'Source reconciled; independent clinical, oncology pharmacy and patient/PPI review pending','source_checked':date,'protocol_id':p['protocol_id'],'code':'00562','protocol_version':'4','title':'Brigatinib Therapy','cycle_days':None,'schedule_kind':'continuous_oral','schedule_label':'Continuous oral treatment with a seven-day lead-in','therapy_label':'Oral ALK-targeted therapy','context_label':'ALK-positive advanced NSCLC · before an ALK inhibitor or after crizotinib','scope_heading':'Brigatinib monotherapy · ALK-positive advanced NSCLC','scope_note':scope,'purpose':'Brigatinib is a targeted medicine intended to control ALK-positive advanced lung cancer. The choice depends on the cancer’s ALK result, previous treatment, your health and your priorities.','indication_text':scope,'schedule_summary':schedule,'administration_text':admin,'monitoring_summary':monitor,'agents':[agent],'sources':sources,'timeline_source_ids':['nccp'],'support_source_ids':['nccp','smpc','oral-antiemetic'],'urgent_source_ids':['nccp','smpc','hse'],'phases_title':'Lead-in, continuing tablets and regular reviews','phases_note':schedule,'medicines_title':'Your targeted medicine','timeline_note':'Relative treatment milestones, not equal time intervals or booked appointments. New symptoms can occur at any time.','safety_note':'Report breathing changes immediately. A normal recent blood test does not make a new symptom safe to ignore.','teachback':'Can you explain the seven-day lead-in, who authorises a dose increase or restart, what to do after a missed or vomited dose, which checks are due and how to get urgent help?','consent_support':'Discuss the exact indication and prior ALK treatment, likely benefit and uncertainty, alternatives including not proceeding, serious lung/heart/liver/glucose/vision risks, common symptoms, fertility and contraception, monitoring and the practical tablet plan. Agree who reviews a hold or restart. Consent can be reconsidered.','urgent_extra':urgent,'chapters':chapters,'phases':[],'timeline':[],'day_groups':[],'support':support,'evidence':{'title':'Why this ALK-targeted medicine may be chosen','intro':'Clinical studies support brigatinib in selected ALK-positive advanced lung cancers before any ALK inhibitor and after crizotinib. The studies involved different treatment settings.','population':'Adults with ALK-positive advanced NSCLC, separated by previous ALK treatment','interpretation':'The medicine can control cancer in appropriately selected people. Your team assesses benefit with symptoms, scans and regular review.','limitations':'Trial averages cannot predict your outcome or establish which modern ALK inhibitor is best for you. Discuss your treatment choices and priorities.','metrics':[],'source_ids':['nccp','alta1l','alta'],'url':alta1},'cycle_display':'reference-chronology','chronology_notes':[{'title':'Before treatment','text':'Confirm ALK and prior treatment, baseline tests, dose, interactions and contacts.'},{'title':'First seven days','text':'Usual 90 mg daily lead-in, with close attention to new respiratory symptoms.'},{'title':'Day eight and beyond','text':'Only increase when authorised; usual ongoing dose is 180 mg daily. Day 8 and 15 pulmonary reviews do not replace urgent reporting.'},{'title':'After a pause','text':restart}],'port_pump':{'required':False,'summary':'Tablets taken at home; no routine IV line, port or infusion pump is required for brigatinib alone.'},'longitudinal_mapping':True,'anatomy':[['lungs','Breathing','Brigatinib','New cough, breathlessness or fever needs immediate advice, especially during the first week.',36,26],['heart','Heart / blood pressure','Brigatinib','Report fainting, slow heartbeat, chest pain or severe headache.',58,29],['liver','Liver tests','Brigatinib','Blood tests check the liver; report jaundice, dark urine or marked illness.',59,39],['pancreas','Glucose / pancreatic enzymes','Brigatinib','Report unusual thirst, frequent urination or severe abdominal pain.',42,45],['muscles','Muscles','Brigatinib','Report unexplained muscle pain or weakness.',68,58],['eyes','Vision','Brigatinib','Report new or worsening blurred vision or other changes.',50,12],['skin','Skin / sun sensitivity','Brigatinib','Use sun protection and report severe rash or sun reaction.',30,55],['bowel','Bowel / nausea','Brigatinib','Report persistent vomiting or severe diarrhoea; keep fluids up as advised.',48,53]],'anatomy_note':'Selected effects of brigatinib; the map does not list every risk or predict when symptoms will occur.','monitoring_schedule':{'title':'When checks happen','columns':stages,'rows':[{'label':l['label'],'cells':l['cells']} for l in lanes if l['kind']=='monitoring'],'note':'Columns show sequence, not equal durations. Continuous tablets do not create a chemotherapy cycle. The team confirms booking, review and any extra tests.','source_ids':['nccp','smpc']},'endocrine_timeline':{'title':'Starting, continuing and reviewing brigatinib','intro':'No dates or personal information are required. Your treating team confirms individual visits and changes.','columns':stages,'rows':[{'label':'Prepare','kind':'checks','start':1,'end':1,'text':'ALK, prior treatment, tests, medicines and consent'},{'label':'Seven-day lead-in','kind':'treatment','start':2,'end':2,'text':'Usual 90 mg daily; watch breathing closely'},{'label':'Continuing tablets','kind':'treatment','start':3,'end':4,'text':'Usual 180 mg daily only if escalation is authorised; continue while helpful and tolerated'},{'label':'Tests and symptoms','kind':'checks','start':2,'end':5,'text':'Scheduled monitoring and immediate reporting of new symptoms'},{'label':'Hold / restart / stop','kind':'checks','start':5,'end':5,'text':'Reason-specific medical review; do not restart or increase yourself'}],'notes':[restart,'Columns show sequence, not equal lengths of time.']},'logistics':{'sections':[item('Prescriptions and supply','Check tablet strengths and the next supply before running out. Keep one written lead-in, increase and review plan.',['nccp','smpc']),item('Home treatment',admin,['nccp','smpc']),item('Visits and blood tests',monitor),item('After a break',restart),item('Contacts and daily life','Keep daytime and out-of-hours numbers available. Agree who books and reviews tests, and ask for support with travel, work or daily tasks.',['hse'])]},'passport_visit_note':'These are reusable review sheets, not a prescribed number of cycles. Record the current tablet dose and agreed next review.','questions':[{'q':'Why does the dose start lower?','a':'The initial seven-day lead-in is part of the brigatinib schedule and helps reduce early pulmonary reactions. Only increase when the team confirms it is appropriate.'},{'q':'What if I miss or vomit a dose?','a':'Do not take an extra dose. Take the next scheduled dose at the usual time. Contact the team for ongoing vomiting or inability to keep fluids or medicine down.'},{'q':'Can I restart my usual tablets after a break?','a':restart},{'q':'Does the first-week breathing warning stop after day seven?','a':'No. Early reactions are especially important, but lung inflammation can also happen later. Report new or worsening breathing symptoms immediately.'},{'q':'How long will I take brigatinib?','a':'There is no fixed number of cycles. Your team reviews benefit, side effects, scans and your priorities and agrees whether to continue, change or stop.'},{'q':'Can I use this page to decide whether tests are safe for treatment?','a':'No. The clinical team combines the protocol, symptoms, previous dose changes and organ function before prescribing.'},{'q':'What belongs in the consent discussion?','a':'Your treatment aim, expected benefit and uncertainty, other options including not proceeding, serious and common harms, lasting effects, fertility and practical concerns. You can ask for more time or explanation and reconsider the decision.'}]}
limits=['ALTA-1L studied ALK-inhibitor-naïve advanced NSCLC; it does not establish adjuvant benefit or benefit after another modern ALK inhibitor.','ALTA was a randomised phase 2 dose-arm study after crizotinib, not a head-to-head comparison against a different ALK inhibitor; cross-trial comparisons are invalid.','ALTA-1L overall survival was not statistically conclusive at final analysis; crossover and later treatment affect interpretation.','NCCP reimbursement codes, the product licence, trial eligibility and an individual treatment recommendation are distinct.','Software source reconciliation is not independent clinical, oncology pharmacy or patient/PPI approval.']
evidence={'trial':'ALTA-1L final analysis; ALTA final long-term analysis','population':'Separate ALK-inhibitor-naïve and crizotinib-refractory adult advanced ALK-positive NSCLC populations.','comparison':'ALTA-1L: brigatinib 180 mg daily after seven-day 90 mg lead-in versus crizotinib 250 mg twice daily. ALTA: brigatinib 180 mg after lead-in versus brigatinib 90 mg daily.','applicability':'Keep NCCP 00562b and 00562a evidence separate. ALTA-1L supports disease-control benefit versus crizotinib before an ALK inhibitor; ALTA documents durable activity after crizotinib. Neither ranks brigatinib against all newer ALK inhibitors.','endpoints':[{'endpoint':'PFS','metric':'ALTA-1L: final blinded independent-review median PFS','intervention_value':24.0,'comparator_value':11.1,'unit':'months','intervention_label':'Brigatinib 180 mg after lead-in','comparator_label':'Crizotinib 250 mg twice daily','hr':'0.48 (95% CI 0.35–0.66)','interpretation':'275 ALK-inhibitor-naïve patients; last patient contact 29 January 2021; brigatinib median follow-up 40.4 months. Measured from randomisation; not an individual prognosis or adjuvant result.','analysis_status':'Final protocol-specified analysis','sources':[{'label':'ALTA-1L final publication','url':alta1},{'label':'EMA SmPC section 5.1 final-analysis date','url':smpc}]},{'endpoint':'PFS','metric':'ALTA final analysis: independent-review median PFS by brigatinib dose arm','intervention_value':16.7,'comparator_value':9.9,'unit':'months','intervention_label':'Arm B: 180 mg after lead-in','comparator_label':'Arm A: 90 mg daily','interpretation':'222 crizotinib-refractory patients randomised; arm B n=110, arm A n=112. Last patient final visit 27 February 2020; final median follow-up 28.3 and 19.6 months respectively, approximately 4.4 years after last enrolment. This is a phase 2 dose-arm comparison, not proof of superiority versus another ALK inhibitor.','analysis_status':'Final long-term trial analysis published 2022','sources':[{'label':'ALTA final publication','url':alta}]}],'limitations':limits,'harms':'Brigatinib requires specific early pulmonary monitoring and later assessment of blood pressure/heart rate, liver, glucose, CPK, pancreatic enzymes and vision. GI, skin and fatigue symptoms can affect daily life. Serious pulmonary events can be fatal. Different studies and follow-up durations should not be used to manufacture cross-drug safety rankings.','overall_survival_note':'ALTA-1L final median OS was not reached in either arm; HR 0.81 (95% CI 0.53–1.22), not a statistically conclusive overall survival advantage. The baseline-brain-metastasis post-hoc signal is exploratory.','sources':[{'label':'ALTA-1L final analysis','url':alta1},{'label':'ALTA final analysis','url':alta},{'label':'EMA Alunbrig SmPC','url':smpc}],'checked':date}
clinical={'component_rationale':agent['explanation'],'key_points':['NCCP 00562 v4 retains the 90 mg seven-day lead-in then 180 mg daily; early ILD prevents routine escalation.','00562a after crizotinib and 00562b ALK-inhibitor naïve are separate indications.','A non-adverse-reaction break ≥14 days needs the source re-lead-in; toxicity breaks use event-specific recovery rules.','Grade 1/2 pneumonitis is held and recurrence reviewed; grade 3/4 or recurrent ILD permanently stops treatment.','CPK >5 × ULN only meets the automatic hold row when grade ≥2 muscle symptoms coexist.','Current NCCP and SmPC disagree about moderate CYP3A inhibitors; resolve with pharmacy.','NCCP count rows explicitly use AND; isolated/mixed low counts need clinical review rather than invented thresholds.'],'patient_selection':{'treatment_intent':'Disease control in ALK-positive advanced NSCLC.','disease_and_biomarker_context':[x['description'] for x in p['indications']],'eligibility_orientation':['Adult, validated ALK result, advanced NSCLC and ECOG 0–2; confirm previous ALK exposure.','Adequate organ function and Consultant Medical Oncologist initiation.','Review contraindications, baseline pulmonary/cardiovascular disease, pregnancy/feeding, organ function and interactions.'],'important_cautions':['Clinically significant ILD/drug pneumonitis or uncontrolled cardiovascular disease are NCCP exclusions.','Recent crizotinib within seven days increases early pulmonary-event risk; this association is not a new mandatory washout.','NCCP uses CrCl <30 for the reduced renal schedule, while current SmPC uses eGFR; do not silently substitute methods.','Severe renal + Child–Pugh C + interaction schedules cannot be multiplied into a new dose.']},'support_summary':[s['text'] for s in support],'baseline':p['monitoring']['baseline'],'before_each_cycle':['Continuous oral treatment: there is no fixed chemotherapy cycle. At each review check current dose, indication, symptoms, adherence, holds, new medicines and due tests.'],'ongoing':p['monitoring']['regular']+p['monitoring']['disease'],'administration':[schedule,admin,restart],'access':['Oral tablets at home; no routine IV access or pump for brigatinib alone.','Agree medicine supply, urgent contacts and ownership of tests and results.'],'rationale':{'summary':evidence['applicability'],'setting':patient['context_label'],'line':'00562a after crizotinib; 00562b before any ALK inhibitor.','factors':['Validated ALK driver, previous systemic/ALK treatment and CNS disease.','Comorbid pulmonary/cardiovascular disease, renal/hepatic function, interactions, adherence and priorities.'],'alternatives':['Discuss current MDT-supported ALK-targeted options, other systemic treatment, trials and supportive care including not proceeding; no cross-trial ranking is implied.'],'limitations':limits,'sources':evidence['sources']}}
journey={'stages':stages,'lanes':lanes,'milestones':[{'title':'Check the exact indication','when':'Before the first dose','why':'Treatment line and ALK result define this pathway.','clinical':'Separate 00562a from 00562b, check validated ALK, baseline tests and interactions.','action':'Confirm written lead-in, monitoring and contact plan.','source_ids':['nccp']},{'title':'Early pulmonary surveillance','when':'First week and scheduled day 8 / day 15 review','why':'Early pulmonary events can occur before the first follow-up.','clinical':'Promptly assess any new respiratory symptom; suspected pneumonitis is held and investigated.','action':'Report immediately; review whether escalation is still appropriate.','source_ids':['nccp','smpc']},{'title':'Ongoing tests','when':'Every two weeks initially for selected tests; monthly for others','why':'Liver, cardiac and metabolic monitoring have different cadences.','clinical':'Liver every two weeks for three months; ECG/BP every two weeks initially then monthly; FBC/renal/glucose/CPK/pancreatic enzymes monthly.','action':'Confirm due window, booking team and result reviewer.','source_ids':['nccp']},{'title':'Restart or stop review','when':'Any pause, dose change or final dose','why':'Reason and duration of a break change the restart plan.','clinical':restart,'action':'Obtain a new individual written plan; retain contraception and five-day sun precautions after stopping.','source_ids':['nccp','smpc']}],'clinical_notes':[scope,restart,'The NCCP first-cycle wording for ECG/BP does not convert continuous oral therapy into a 21- or 28-day chemotherapy cycle.']}
splan={'id':'continuous_oral','label':'Brigatinib alone · lead-in and continuing tablets','active_medicines':['brigatinib'],'active_drugs':['brigatinib'],'emetogenic_risk':'oral_minimal_low','medicines':[],'additional_support':['Minimal-to-low oral emetogenic risk: antiemetic treatment as required only, with an individual prescribed choice/dose/duration and interaction review.','No routine premedication is required by NCCP. NCIS V8 parenteral schedules should not be copied as routine daily prophylaxis for this oral medicine.',admin,restart,repro,support[3]['text'],'Review CPK/muscle, pancreatic, glucose, blood pressure/heart rate and liver results; separate medicine-specific management from prophylaxis.'],'source_page':'1–7; oral guidance Table 5 page 8 and Table 8 page 13','source_url':src,'source_checked':date,'guidance':{'label':'NCCP oral SACT antiemetic guidance V6, minimal-to-low risk (as required); NCIS V8 reviewed for scope','url':oral},'additional_sources':[{'label':'NCIS Medical Oncology antiemetics V8','url':ncis}]}
