for id,label,detail,tier in [('pulmonary','Early pulmonary reactions / pneumonitis','Severe or fatal lung inflammation can occur, particularly in the first week and also later. Report new cough or breathlessness immediately.','serious'),('cardiovascular','Hypertension / bradycardia','High blood pressure and a slow heartbeat need monitoring; fainting, severe headache or chest symptoms need urgent assessment.','serious'),('liver','Liver injury','Liver tests are monitored closely, especially in the first three months; serious liver injury can require stopping treatment.','serious'),('metabolic','Hyperglycaemia and pancreatic enzyme elevations','Glucose and pancreatic enzymes can rise. Report unusual thirst, frequent urination or severe abdominal pain.','serious'),('muscle','CPK elevation / muscle symptoms','Raised CPK may occur with muscle pain or weakness; prompt reporting and blood tests guide treatment changes.','important'),('vision','Visual disturbance','New or worsening visual symptoms need assessment; severe changes can require stopping treatment.','serious'),('gi','Diarrhoea, nausea, vomiting and appetite change','Symptoms can impair hydration and tablet-taking; seek advice for severe or persistent problems.','important'),('skin','Rash / photosensitivity','Skin reactions and sun sensitivity can occur; use sun protection during treatment and for at least five days afterwards.','important'),('counts','Low blood counts / infection','Blood-count changes and infection can occur; report fever, shivering or sudden illness.','serious'),('pregnancy','Pregnancy, breastfeeding and fertility','Potential foetal harm and male fertility effects require discussion. Breastfeeding must stop during treatment; follow medicine-specific contraception advice.','serious')]:cp['risks'].append({'id':id,'label':label,'detail':detail,'tier':tier,'source_ids':['nccp','smpc']})
